SELECT * FROM development_patent as dp,student_information as si
        where dp.student_number=si.student_number
            and si.classes = #{className}
            and si.major = #{major}
            and si.college = #{college}
            and si.grade = #{grade}

SELECT * FROM development_patent as dp,student_information as si
        where dp.student_number=si.student_number
            and si.college = #{college}

SELECT *
FROM development_patent AS dp
JOIN student_information AS si ON dp.student_number = si.student_number


        AND dp.student_name LIKE CONCAT('%',#{studentName},'%')


        AND dp.student_number LIKE CONCAT('%',#{studentNumber},'%')


        AND si.classes = #{classes}


        AND si.grade = #{grade}


        AND si.major = #{major}


        AND si.college = #{college}
